INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(3401, 'Leviticus 26:10', 'Leviticus', 26, 10, '&nbsp;تاسو سره به دومره ډېره غله وى چې تاسو به هغه زَړه غله د دې دپاره وغورزوئ چې د نوى فصل دپاره ځائ پېدا شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3402, 'Leviticus 26:11', 'Leviticus', 26, 11, '&nbsp;زۀ به ستاسو په مينځ کښې زما په مقدسه خېمه کښې اوسېږم او زۀ به ستاسو نه کله هم نفرت ونۀ کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3403, 'Leviticus 26:12', 'Leviticus', 26, 12, '&nbsp;زۀ به ستاسو مل يم، زۀ به ستاسو خُدائ پاک يم او تاسو به زما خلق يئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3404, 'Leviticus 26:13', 'Leviticus', 26, 13, '&nbsp;زۀ مالِک خُدائ ستاسو خُدائ پاک يم، چا چې تاسو د مِصر د مُلک نه راوويستلئ چې د غلامۍ نه آزاد شئ. ما هغه طاقت ختم کړو چې تاسو يې ټيټ کړى وئ او د دې جوګه مې کړئ چې په اوچتو سترګو ګرځئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3405, 'Leviticus 26:14', 'Leviticus', 26, 14, '&nbsp;مالِک خُدائ وفرمائيل، ”کۀ تاسو زما حُکمونه ونۀ منل، نو تاسو ته به سزا مِلاو شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3406, 'Leviticus 26:15', 'Leviticus', 26, 15, '&nbsp;کۀ تاسو زما د حُکمونو منلو نه اِنکار وکړئ او زما د حُکمونو نه کرکه وکړئ او زما لوظ مات کړئ،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3407, 'Leviticus 26:16', 'Leviticus', 26, 16, '&nbsp;نو زۀ به تاسو له سزا درکړم. زۀ به په تاسو افتونه راولم يعنې لا علاجه بيمارۍ او تبې چې تاسو به ړاندۀ کړى او ستاسو ژوند به لنډ تنګ کړم. تاسو به تخم وکَرئ، خو هيڅ ګټه به درنۀ کړى، ځکه چې ستاسو دشمنان به په تاسو غالِب شى او چې تاسو څۀ کَرلى وى نو هغوئ به يې وخورى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3408, 'Leviticus 26:17', 'Leviticus', 26, 17, '&nbsp;زۀ به ستاسو نه مخ واړوم، نو تاسو به شکست وخورئ او هغه خلق چې ستاسو نه نفرت کوى هغوئ به په تاسو حکومت وکړى، تاسو به دومره يرېږئ چې څوک درپسې نۀ وى بيا به هم منډې وهئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3409, 'Leviticus 26:18', 'Leviticus', 26, 18, '&nbsp;کۀ د دې هر څۀ نه پس بيا هم ما ته غوږ ونۀ نيسئ، نو ستاسو د نافرمانۍ په وجه زۀ به ستاسو سزا اووۀ چنده زياته کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3410, 'Leviticus 26:19', 'Leviticus', 26, 19, '&nbsp;زۀ به ستاسو غرور مات کړم، باران به نۀ وريږى او ستاسو زمکه به اوچه شى او د کاڼى په شان به سخته شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3411, 'Leviticus 26:20', 'Leviticus', 26, 20, '&nbsp;ستاسو ټول محنت به تاسو له هيڅ فائده درنۀ کړى، ځکه چې ستاسو زمکه به فصلونه نۀ کوى او ستاسو ونې به مېوه نۀ نيسى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3412, 'Leviticus 26:21', 'Leviticus', 26, 21, '&nbsp;کۀ تاسو بيا هم زما مخالفت کوئ او زما د منلو نه اِنکار کوئ، نو زۀ به ستاسو سزا اووۀ چنده زياته کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3413, 'Leviticus 26:22', 'Leviticus', 26, 22, '&nbsp;زۀ به ستاسو مينځ ته خطرناک ځناور درولېږم او دا به ستاسو ماشومان ووژنى، ستاسو څاروى به تباه کړى او ستاسو شمېر به دومره کم کړم چې سړکونه به مو خوشى پاتې شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3414, 'Leviticus 26:23', 'Leviticus', 26, 23, '&nbsp;کۀ د دې هر څۀ نه پس هم زما خبرې ته غوږ ونۀ نيسئ او بيا هم زما مخالفت کوئ،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3415, 'Leviticus 26:24', 'Leviticus', 26, 24, '&nbsp;نو زۀ به هم ستاسو خِلاف شم او زۀ به تاسو له د مخکښې نه اووۀ چنده زياته سزا درکړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3416, 'Leviticus 26:25', 'Leviticus', 26, 25, '&nbsp;زۀ به په تاسو يو جنګ راولم، زما د لوظ د ماتولو سزا به درکړم او کۀ تاسو په خپلو ښارونو کښې د امن دپاره راغونډ شئ، نو زۀ به په تاسو لا علاجه بيمارۍ راولېږم او تاسو به زۀ ستاسو دشمنانو ته حواله کړم نو هغوئ به په تاسو حکومت وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3417, 'Leviticus 26:26', 'Leviticus', 26, 26, '&nbsp;زۀ به په تاسو خوراک بند کړم، نو د لسو کورَنو اوړۀ به يو ښانک کښې يو ځائ تيارولے شى. هغوئ سره به خوراک ختم شى او چې کله تاسو هر څۀ وخورئ، نو بيا به هم اوږى يئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3418, 'Leviticus 26:27', 'Leviticus', 26, 27, '&nbsp;کۀ د دې هر څۀ نه پس هم زما خبرې ته غوږ ونۀ نيسئ او زما د منلو نه اِنکار وکړئ،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3419, 'Leviticus 26:28', 'Leviticus', 26, 28, '&nbsp;نو زما قهر به ستاسو خِلاف شى او بيا به زۀ ستاسو سزا د مخکښې نه اووۀ چنده زياته کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3420, 'Leviticus 26:29', 'Leviticus', 26, 29, '&nbsp;ستاسو لوږه به دومره زياته شى چې خپل بچى به وخورئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3421, 'Leviticus 26:30', 'Leviticus', 26, 30, '&nbsp;زۀ به ستاسو علاقائى عبادتخانې تباه کړم، ستاسو د خوشبويۍ قربان‌ګاه به ختمه کړم او ستاسو مړى به د ستاسو په بې‌ساه بُتانو باندې وروغورزوم. زۀ به ستاسو نه نفرت وکړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3422, 'Leviticus 26:31', 'Leviticus', 26, 31, '&nbsp;زۀ به ستاسو د ښارونو نه کنډرې جوړې کړم، ستاسو د عبادت ځايونه به تباه کړم او ستاسو قربانۍ به قبولې نۀ کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3423, 'Leviticus 26:32', 'Leviticus', 26, 32, '&nbsp;زۀ به ستاسو مُلک داسې تباه کړم چې کوم دشمنان دا مُلک ونيسى نو هغوئ به په دې تباهۍ باندې غمژن شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3424, 'Leviticus 26:33', 'Leviticus', 26, 33, '&nbsp;زۀ به په تاسو جنګ راولم او په پردو مُلکونو کښې به مو خوارۀ وارۀ کړم. ستاسو مُلک به خوشے پاتې شى او ستاسو ښارونه به وران ويجاړ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3425, 'Leviticus 26:36', 'Leviticus', 26, 36, '&nbsp;ستاسو کوم کسان چې د دشمن په مُلک کښې وى هغوئ به دومره ويروم چې د هوا په وجه د پاڼې د معمولى کش نه به هم تښتى. تاسو به داسې منډې وهئ لکه څوک چې په جنګ کښې په تاسو پسې وى او ستاسو سره به نزدې هيڅ دشمن نۀ وى خو تاسو به بيا هم غورزېږئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3426, 'Leviticus 26:37', 'Leviticus', 26, 37, '&nbsp;کله چې هيڅ څوک هم په تاسو پسې نۀ وى نو تاسو به په يو بل باندې غورزېږئ او تاسو به د دې جوګه نۀ يئ چې د دشمن په مخکښې ودرېږئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3427, 'Leviticus 26:38', 'Leviticus', 26, 38, '&nbsp;ستاسو د دشمنانو مُلک به تاسو ژوندى تېر کړى، تاسو به پردى مُلک کښې مړۀ شئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3428, 'Leviticus 26:39', 'Leviticus', 26, 39, '&nbsp;ستاسو کوم کسان چې ستاسو د دشمنانو په مُلک کښې ژوندى پاتې وى هغوئ به خراب‌تُراب شى، ستاسو خپلې ګناه او ستاسو د پلار نيکۀ د ګناه په وجه به داسې وشى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3429, 'Leviticus 26:40', 'Leviticus', 26, 40, '&nbsp;خو ستاسو اولاد به د خپلو ګناهونو او د هغوئ د پلار نيکۀ د ګناهونو اِقرار وکړى، چې هغوئ زما سره بې‌وفائى کړې ده او زما خِلاف يې سرکشى کړې ده،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3430, 'Leviticus 26:41', 'Leviticus', 26, 41, '&nbsp;او زۀ يې د خپل ځان خِلاف کړم او چې هغوئ د دشمنانو مُلک ته ولېږم. کۀ بيا ستاسو د اولاد سخت زړونه نرم شى او د خپلې ګناه او سرکشۍ سزا ورته مِلاو شى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3431, 'Leviticus 26:42', 'Leviticus', 26, 42, '&nbsp;نو زۀ به د يعقوب، اِسحاق او اِبراهيم سره خپل کړے لوظ راياد کړم او زۀ به خپل هغه لوظ بيا تازه کړم چې خپلو خلقو له هغه مُلک ورکړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3432, 'Leviticus 26:43', 'Leviticus', 26, 43, '&nbsp;اول خو به هغه مُلک خامخا د هغې د خلقو نه خالى کيږى، چې دا د پوره آرام نه ښۀ خوند واخلى او هغوئ ته به زما د قانون او حُکمونو نۀ منلو په وجه پوره سزا مِلاو شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3433, 'Leviticus 26:44', 'Leviticus', 26, 44, '&nbsp;خو بيا هم، چې هغوئ لا د خپلو دشمنانو په مُلک کښې وى، نو زۀ به يې نۀ رد کوم، نۀ به ترې نفرت کوم او نۀ به يې بېخى تباه کوم. هسې نه چې د هغوئ سره زما لوظ مات شى، زۀ مالِک خُدائ د هغوئ خُدائ پاک يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3434, 'Leviticus 26:45', 'Leviticus', 26, 45, '&nbsp;زۀ به هغه لوظ بيا تازه کړم چې ما د هغوئ د پلار نيکۀ سره کړے وو کله چې ما ټولو قومونو ته خپل طاقت وښودلو چې خپل خلق مې د مِصر مُلک نه راوويستل، چې زۀ مالِک خُدائ، د هغوئ خُدائ پاک اوسم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3435, 'Leviticus 26:46', 'Leviticus', 26, 46, '&nbsp;دا ټول هغه قانون او حُکمونه دى چې مالِک خُدائ موسىٰ له د سينا په غرۀ باندې د بنى اِسرائيلو دپاره ورکړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3436, 'Leviticus 27:1', 'Leviticus', 27, 1, '&nbsp;بيا مالِک خُدائ موسىٰ ته وفرمائيل چې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3437, 'Leviticus 27:2', 'Leviticus', 27, 2, '&nbsp;”بنى اِسرائيلو ته دا اصُول وښايه. کله چې د يو خاص منښتې په پوره کېدو کښې يو کس مالِک خُدائ ته وقف کيږى، نو هغه به د دې قيمت په ورکولو سره آزاد کړے شى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3438, 'Leviticus 27:8', 'Leviticus', 27, 8, '&nbsp;کۀ يو کس منښته منلې وى او ډېر غريب وى چې هغه معيارى قيمت نۀ شى ورکولے، نو هغه کس دې اِمام له راولى او اِمام به کم قيمت مقرر کړى، چې د هغه کس د وس په مطابق وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3439, 'Leviticus 27:9', 'Leviticus', 27, 9, '&nbsp;کۀ هغه منښته د يو ځناور وى چې مالِک خُدائ ته د يوې نذرانې په توګه د قبلېدو قابل وى، نو داسې تُحفه چې مالِک خُدائ ته پېش کيږى هغه مقدسه ده،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3440, 'Leviticus 27:10', 'Leviticus', 27, 10, '&nbsp;او کۀ يو کس منښته ومنى نو هغه ځناور په بل ځناور نۀ شى بدلېدلے. کۀ چرې هغه بدل کړى، نو داوړه ځناور به د مالِک خُدائ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3441, 'Leviticus 27:11', 'Leviticus', 27, 11, '&nbsp;خو کۀ هغه ځناور حرام وى، کوم چې مالِک خُدائ ته د نذرانې په توګه د قبلېدو قابل نۀ وى، نو هغه کس به هغه ځناور اِمام له بوځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3442, 'Leviticus 27:12', 'Leviticus', 27, 12, '&nbsp;اِمام به د دې ښۀ‌والى او بد‌والى په مطابق قيمت مقرر کړى او دا به آخرى قيمت وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3443, 'Leviticus 27:13', 'Leviticus', 27, 13, '&nbsp;کۀ هغه کس دا واپس اخستل غواړى، نو هغه به د دې قيمت سره شل فيصده سېوا ورکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3444, 'Leviticus 27:14', 'Leviticus', 27, 14, '&nbsp;کله چې يو کس خپل کور مالِک خُدائ ته وقف کوى، نو اِمام به د دې د ښۀ‌والى يا بد‌والى په مطابق د دې قيمت مقرر کړى او دا به آخرى قيمت وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3445, 'Leviticus 27:15', 'Leviticus', 27, 15, '&nbsp;کۀ هغه کس چا چې دا کور وقف کړے وى او دا واپس اخستل غواړى، نو هغه به خامخا د دې قيمت سره شل فيصده زيات ورکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3446, 'Leviticus 27:16', 'Leviticus', 27, 16, '&nbsp;کۀ څوک د خپلې زمکې څۀ حِصه مالِک خُدائ ته وقف کوى، نو د دې قيمت به د هغه تخم په مطابق مقررولے شى چې څومره په کښې کَرل په کار وى، دا قيمت به د سپينو زرو لس سيکې د شلو کلو اوربشو دپاره وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3447, 'Leviticus 27:17', 'Leviticus', 27, 17, '&nbsp;کۀ هغه کس دا زمکه د واپس اخستلو کال باندې وقف کړى، نو د دې زمکې قيمت به پوره ورکولے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3448, 'Leviticus 27:18', 'Leviticus', 27, 18, '&nbsp;خو کۀ چرې هغه کس خپله زمکه د دې نه وروستو وقف کړى، اِمام به د هغې بيعه د هغه کالونو د شمېر په مطابق حساب کړى چې د واپس اخستلو تر راتلونکى کال پورې پاتې وى او د کالونو د کمى په وجه به کمه بيعه مقرر کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3449, 'Leviticus 27:19', 'Leviticus', 27, 19, '&nbsp;چا چې دا زمکه وقف کړې وى کۀ هغه کس دا واپس اخستل وغواړى، نو هغه به خامخا د دې قيمت سره شل فيصده زيات ورکوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3450, 'Leviticus 27:20', 'Leviticus', 27, 20, '&nbsp;کۀ هغه کس دا زمکه د مالِک خُدائ نه واپس اخستلو نه مخکښې په بل چا باندې خرڅه کړى، نو د هغۀ حق نۀ جوړيږى چې دا واپس واخلى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3451, 'Leviticus 27:21', 'Leviticus', 27, 21, '&nbsp;د واپس اخستلو پسې کال به هغه پټے د همېشه دپاره د مالِک خُدائ شى، دا به د اِمامانو وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3452, 'Leviticus 27:22', 'Leviticus', 27, 22, '&nbsp;کۀ څوک مالِک خُدائ ته يو پټے وقف کوى چې هغۀ اخستے وى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3453, 'Leviticus 27:23', 'Leviticus', 27, 23, '&nbsp;اِمام به د واپس اخستلو پسې کال پورې د کالونو د شمېر په مطابق د دې د قيمت اندازه ولګوى او هغه کس به خامخا هم په هغه ورځ د دې قيمت ورکړى، دا پېسې به د مالِک خُدائ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3454, 'Leviticus 27:24', 'Leviticus', 27, 24, '&nbsp;د واپس اخستلو په کال به دا پټے واپس د دې اصلى مالِک يا د هغۀ اولاد ته ملاويږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3455, 'Leviticus 27:25', 'Leviticus', 27, 25, '&nbsp;ټول قيمتونه به د منلے شوى معيار په مطابق مقررولے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3456, 'Leviticus 27:26', 'Leviticus', 27, 26, '&nbsp;په ځناورو کښې د ټولو نه وړومبى پېدا شوى بچى د مالِک خُدائ وى، نو هيڅ څوک دا هغۀ ته د يوې رضاکارانه نذرانې په توګه نۀ شى پېش کولے. يو سخے، ګډُورے يا يو د چېلۍ بچے دا د مالِک خُدائ وى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3457, 'Leviticus 27:27', 'Leviticus', 27, 27, '&nbsp;خو وړومبے پېدا شوے يو حرام ځناور د معيارى قيمت سره شل فيصده زيات ورکولو باندې واپس اخستلے شى. کۀ دا واپس وانۀ خستلے شى، نو دا دې په چا باندې په معيارى قيمت خرڅ کړے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3458, 'Leviticus 27:28', 'Leviticus', 27, 28, '&nbsp;کوم څيز چې مالِک خُدائ ته بغېر د څۀ شرط نه وقف شوے وى، نو هيڅ څوک به دا نۀ خرڅولے شى او نۀ به يې واپس اخستلے شى، کۀ هغه بنى آدم، ځناور، يا زمکه وى، دا به د همېشه دپاره د مالِک خُدائ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3459, 'Leviticus 27:29', 'Leviticus', 27, 29, '&nbsp;کۀ په چا باندې د مرګ فېصله شوې وى نو هغه به خامخا وژلے شى او واپس به نۀ شى اخستلے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3460, 'Leviticus 27:30', 'Leviticus', 27, 30, '&nbsp;د زمکې د ټول پېداوار لسمه حِصه د مالِک خُدائ ده، کۀ هغه غله وى يا مېوه وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3461, 'Leviticus 27:31', 'Leviticus', 27, 31, '&nbsp;کۀ يو کس دا واپس اخستل غواړى، نو هغه به خامخا د منلے شوى قيمت سره شل فيصده زيات ورکوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3462, 'Leviticus 27:32', 'Leviticus', 27, 32, '&nbsp;هر يو لسم څاروے د مالِک خُدائ دے. کله چې ځناور شمېرلے شى، نو هر يو لسم به د مالِک خُدائ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3463, 'Leviticus 27:33', 'Leviticus', 27, 33, '&nbsp;مالِک دې ځناورو له داسې ترتيب نۀ ورکوى چې خراب ځناور ترې خوښ کړے شى او بدلولے رابدلولے يې هم نۀ شى. کۀ هغۀ يو ځناور په بل ځناور بدل کړو، نو بيا به دواړه د مالِک خُدائ وى او واپس به نۀ شى اخستلے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3464, 'Leviticus 27:34', 'Leviticus', 27, 34, '&nbsp;دا هغه حُکمونه دى چې مالِک خُدائ موسىٰ له د سينا په غرۀ باندې د بنى اِسرائيلو دپاره ورکړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3465, 'Numbers 1:1', 'Numbers', 1, 1, '&nbsp;د دوېم کال د دوېمې مياشتې په وړومبۍ ورځ بنى اِسرائيلو د مِصر مُلک پرېښودو نه پس، د سينا په بيابان کښې مالِک خُدائ د خپل حضور په مقدسه خېمه کښې موسىٰ ته وفرمائيل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3466, 'Numbers 1:2', 'Numbers', 1, 2, '&nbsp;”تۀ او هارون د ټولو بنى اِسرائيلو د قبيلو او کورَنو مردم‌شمارى وکړئ. د هغه ټولو سړو نومونه وليکئ', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3467, 'Numbers 1:3', 'Numbers', 1, 3, '&nbsp;چې عُمر يې شل کاله يا د دې نه زيات وى او چې جنګ کولے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3468, 'Numbers 1:4', 'Numbers', 1, 4, '&nbsp;د هرې قبيلې نه يو يو مشر راوغواړه چې ستا مدد وکړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3469, 'Numbers 1:17', 'Numbers', 1, 17, '&nbsp;د دې دولسو سړو په مدد سره موسىٰ او هارون،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3470, 'Numbers 1:18', 'Numbers', 1, 18, '&nbsp;د دوېمې مياشتې په اوله ورځ د بنى اِسرائيلو ټول قوم راغونډ کړو او د ټولو خلقو نومونه يې د قبيلو او کورَنو په مطابق وليکل. د هغه ټولو سړو نومونه وليکلے شول او وشمېرلے شول چې عُمر يې شل کاله يا د دې نه زيات وو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3471, 'Numbers 1:19', 'Numbers', 1, 19, '&nbsp;هم هغه شان چې څنګه مالِک خُدائ حُکم ورکړے وو. د سينا په بيابان کښې، موسىٰ خلق وشمېرل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3472, 'Numbers 1:47', 'Numbers', 1, 47, '&nbsp;د ليويانو نومونه د نورو قبيلو سره نۀ وُو ليکلے شوى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3473, 'Numbers 1:48', 'Numbers', 1, 48, '&nbsp;ځکه چې مالِک خُدائ موسىٰ ته فرمائيلى وُو چې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3474, 'Numbers 1:49', 'Numbers', 1, 49, '&nbsp;”کله چې تۀ د هغه سړو مردم‌شمارى کوې چې جنګ کولے شى، نو د ليوى قبيله په کښې مۀ شاملوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3475, 'Numbers 1:50', 'Numbers', 1, 50, '&nbsp;خو ليويان زما د حضور مقدسې خېمې او د دې د ټول سامان مشران مقرر کړه. هغوئ به خېمه او د دې سامان وړى، خِدمت به کوى او د دې نه ګېرچاپېره به خېمې لګوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3476, 'Numbers 1:51', 'Numbers', 1, 51, '&nbsp;هر کله چې تاسو خېمې بل ځائ ته اوړئ نو ليويان به مقدسه خېمه راټولوى او په هر يو نوى ځائ کښې به يې لګوى. بل هر څوک چې مقدسې خېمې ته ورنزدې شى نو وبه وژلے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3477, 'Numbers 1:52', 'Numbers', 1, 52, '&nbsp;او نور اِسرائيليان به قبيله په قبيله خېمې ودروى، هر يو سړے به د خپلې قبيلې سره وى او د خپلې جنډې لاندې به وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3478, 'Numbers 1:53', 'Numbers', 1, 53, '&nbsp;خو ليويان به د مقدسې خېمې د حِفاظت دپاره د دې نه ګېرچاپېره خېمې ولګوى، چې څوک نزدې رانۀ شى، هسې نه چې د بنى اِسرائيلو قوم ته زۀ په قهر شم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3479, 'Numbers 1:54', 'Numbers', 1, 54, '&nbsp;نو بنى اِسرائيلو هم هغه شان وکړل څنګه چې مالِک خُدائ موسىٰ ته حُکم کړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3480, 'Numbers 2:1', 'Numbers', 2, 1, '&nbsp;بيا مالِک خُدائ موسىٰ او هارون ته دا اصُول وښودل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3481, 'Numbers 2:2', 'Numbers', 2, 2, '&nbsp;کله چې اِسرائيليان کېمپ جوړوى، نو هر سړے به د خپل لښکر د جنډې لاندې خېمه ودروى. خېمې به د مقدسې خېمې نه ګېرچاپېره لګولے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3482, 'Numbers 2:17', 'Numbers', 2, 17, '&nbsp;بيا دې د اولنو دوه لښکرو او د وروستنو دوه لښکرو په مينځ کښې ليويان روان شى چې مقدسه خېمه يوسى. هر يو لښکر به هم په هغه ترتيب روان وى چې څنګه خېمې ودروى، هر يو به په خپل خپل ځائ د خپلې جنډې لاندې وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3483, 'Numbers 2:32', 'Numbers', 2, 32, '&nbsp;د بنى اِسرائيلو د ټولو لښکرو شمېر شپږ لاکه درې زره پينځۀ سوه او پنځوس کسان وُو چې قبيله په قبيله د هغوئ نومونه وليکلے شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3484, 'Numbers 2:33', 'Numbers', 2, 33, '&nbsp;هم هغه شان چې څنګه مالِک خُدائ موسىٰ ته حُکم کړے وو، ليويان د نورو بنى اِسرائيلو سره يو ځائ ونۀ شمېرلے شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3485, 'Numbers 2:34', 'Numbers', 2, 34, '&nbsp;بنى اِسرائيلو هم هغه شان وکړل چې څنګه مالِک خُدائ موسىٰ ته حُکم کړے وو. هغوئ هر يو د خپلې جنډې لاندې خېمې ودرولې او هر يو د خپلې قبيلې سره روان وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3486, 'Numbers 3:1', 'Numbers', 3, 1, '&nbsp;دا د هارون او د موسىٰ د خاندان د هغه وخت خبره ده کله چې مالِک خُدائ د سينا په غرۀ باندې د موسىٰ سره خبرې وکړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3487, 'Numbers 3:2', 'Numbers', 3, 2, '&nbsp;د هارون څلور زامن وُو، ندب چې د ټولو مشر وو، ابيهُو، اِلى‌عزر او اِتمر.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3488, 'Numbers 3:3', 'Numbers', 3, 3, '&nbsp;د هغوئ سرونه غوړ کړے شول او د اِمامانو په توګه مقرر کړے شول،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3489, 'Numbers 3:4', 'Numbers', 3, 4, '&nbsp;خو ندب او ابيهُو هغه وخت ووژلے شول چې کله هغوئ د سينا په بيابان کښې مالِک خُدائ ته هغه اور پېش کولو چې د هغې اجازت نۀ وو. د هغوئ هيڅ اولاد نۀ وو، نو اِلى‌عزر او اِتمر د خپل پلار هارون په ژوندون کښې د اِمامانو په توګه خِدمت کولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3490, 'Numbers 3:5', 'Numbers', 3, 5, '&nbsp;بيا مالِک خُدائ موسىٰ ته وفرمائيل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3491, 'Numbers 3:6', 'Numbers', 3, 6, '&nbsp;”د ليويانو قبيله نزدې راوله او هغوئ د هارون اِمام دپاره خِدمتګاران مقرر کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3492, 'Numbers 3:7', 'Numbers', 3, 7, '&nbsp;هغوئ به زما د حضور په مقدسه خېمه کار کوى او د اِمامانو او د ټول قوم دپاره به ذمه وارى پوره کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
