(3494, 'Numbers 3:9', 'Numbers', 3, 9, '&nbsp;ليويان د هارون او د هغۀ د زامنو د خِدمت دپاره وقف شوى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3495, 'Numbers 3:10', 'Numbers', 3, 10, '&nbsp;تۀ به هارون او د هغۀ زامن مقرر کړې چې د اِمامانو په توګه ذمه وارى پوره کړى، بل هر څوک چې مقدسې خېمې ته د ورنزدې کېدلو کوشش وکړى نو هغه به ووژلے شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3496, 'Numbers 3:11', 'Numbers', 3, 11, '&nbsp;نو مالِک خُدائ موسىٰ ته وفرمائيل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
